import { expect, test } from "bun:test";

import { encodeTacitPaymasterData } from "../src/paymaster-data";

// The same sample and bytes as `test_sdkEncodingMatches` in test/TacitPaymaster.t.sol.
test("encodeTacitPaymasterData matches TacitPaymaster.PaymasterData", () => {
    const data = encodeTacitPaymasterData(
        "0x000000c2A20657CE25f2Ba99737933D031AFBEE9",
        [1n, 2n],
        [
            [3n, 4n],
            [5n, 6n],
        ],
        [7n, 8n],
        [10n, 11n, 12n, 13n, 14n, 15n, 16n, 17n, 18n, 0n, 0n],
        "0x0000000000000000000000000000000005A71cE2",
        -900000000000000000n,
        100000000000000000n
    );

    expect(data).toBe("");
});

test("encodeTacitPaymasterData needs all eleven public inputs", () => {
    expect(() =>
        encodeTacitPaymasterData(
            "0x000000c2A20657CE25f2Ba99737933D031AFBEE9",
            [1n, 2n],
            [
                [3n, 4n],
                [5n, 6n],
            ],
            [7n, 8n],
            [1n],
            "0x0000000000000000000000000000000005A71cE2",
            -1n,
            0n
        )
    ).toThrow("11 entries");
});
